CHECK (
      (
        reconciliation_state IN ('none', 'resolved')
        AND reconciliation_reason IS NULL
      )
      OR (
        reconciliation_state IN ('required', 'in_progress', 'manual_review')
        AND reconciliation_reason IS NOT NULL
      )
    )

